// And groups predicates with the AND operator between them.
func And(predicates ...predicate.MediaPackage) predicate.MediaPackage {
	return predicate.MediaPackage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.MediaPackage) predicate.MediaPackage {
	return predicate.MediaPackage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.MediaPackage) predicate.MediaPackage {
	return predicate.MediaPackage(sql.NotPredicates(p))
}
